comms.text:
@1 וּקְרֵב לְוָתֵהּ יְהוּדָה וַאֲמַר בְּבָעוּ רִבּוֹנִי יְמַלֵּל כְּעַן עַבְדָּךְ פִּתְגָּמָא קֳדָם רִבּוֹנִי וְלָא יִתְקֵף רוּגְזָךְ בְּעַבְדָּךְ אֲרֵי כְפַרְעֹה כֵּן אָתְּ:
@2 רִבּוֹנִי שְׁאִיל יָת עַבְדּוֹהִי לְמֵימָר הַאִית לְכוֹן אַבָּא אוֹ אָחָא:
@3 וַאֲמַרְנָא לְרִבּוֹנִי אִית לָנָא אַבָּא סָבָא וּבַר סִיבְתִין זְעֵיר וְאָחוּהִי מִית וְאִשְׁתָּאַר הוּא בִלְחוֹדוֹהִי לְאִמֵּהּ וַאֲבוּהִי רְחִים לֵהּ:
@4 וַאֲמַרְתָּ לְעַבְדָּיךְ אֲחִיתוֹהִי לְוָתִי וֶאֱשַׁוֵּי עֵינִי עֲלוֹהִי:
@5 וַאֲמַרְנָא לְרִבּוֹנִי לָא יִכּוּל עוּלֵימָא לְמִשְׁבַּק יָת אֲבוּהִי וְאִם יִשְׁבּוֹק יָת אֲבוּהִי וּמִית:
@6 וַאֲמַרְתָּ לְעַבְדָּיךְ אִם לָא יֵחוֹת אֲחוּכוֹן זְעֵירָא עִמְּכוֹן לָא תוֹסְפוּן לְמֶחֱזֵי אַפָּי:
@7 וַהֲוָה כַּד סְלֵיקְנָא לְעַבְדָּךְ אַבָּא וְחַוֵּינָא לֵהּ יָת פִּתְגָּמֵי רִבּוֹנִי:
@8 וַאֲמַר אָבוּנָא תּוּבוּ זְבוּנוּ לָנָא זְעֵיר עִיבוּרָא:
@9 וַאֲמַרְנָא לָא נִכּוּל לְמֵיחָת אִם אִית אָחוּנָא זְעֵירָא עִמָּנָא וְנֵחוֹת אֲרֵי לָא נִכּוּל לְמֶחֱזֵי אַפֵּי גַּבְרָא וְאָחוּנָא זְעֵירָא לֵיתוֹהִי עִמָּנָא:
@10 וַאֲמַר עַבְדָּךְ אַבָּא לָנָא אַתּוּן יְדַעְתּוּן אֲרֵי תְרֵין יְלִידַת לִי אִתְּתִי:
@11 וּנְפַק חַד מִלְוָתִי וַאֲמָרִית בְּרַם מִקְטַל קְטִיל וְלָא חֲזִתֵּהּ עַד כְּעָן:
@12 וְתַדְבְּרוּן אַף יָת דֵּין מִן קֳדָמַי וִיעַרְעִנֵּהּ מוֹתָא וְתַחֲתוּן יָת שִׂבְתִי בְּבִישְׁתָא לִשְׁאוֹל:
@13 וּכְעַן כְּמֵיתִי לְוַת עַבְדָּךְ אַבָּא וְעוּלֵימָא לֵיתוֹהִי עִמָּנָא וְנַפְשֵׁהּ חֲבִיבָא לֵהּ כְּנַפְשֵׁהּ:
@14 וִיהֵי כַּד יֶחֱזֵי אֲרֵי לֵית עוּלֵימָא וּמִית וְיַחֲתוּן עַבְדָּיךְ יָת שִׂיבַת עַבְדָּךְ אָבוּנָא בְּדָווֹנָא לִשְׁאוֹל:
@15 אֲרֵי עַבְדָּךְ מְעָרַב בְּעוּלֵימָא מִן אַבָּא לְמֵימָר אִם לָא אַיְתִנֵּהּ לְוָתָךְ וָאֱהִי חָטֵי לְאַבָּא כָּל יוֹמַיָּא:
@16 וּכְעַן יֵתֶב כְּעַן עַבְדָּךְ תְּחוֹת עוּלֵימָא עַבְדָּא לְרִבּוֹנִי וְעוּלֵימָא יִסַּק עִם אֲחוֹהִי:
@17 אֲרֵי אֶכְדֵּין אֶסַּק לְוַת אַבָּא וְעוּלֵימָא לֵיתוֹהִי עִמִּי דִּלְמָא אֶחֱזֵי בְּבִישׁוּ דִּי יִשְׁכַּח יָת אַבָּא:
@18 וְלָא יְכִיל יוֹסֵף לְאִתְחַסָּנָא לְכֹל דְּקָיְמִין עִלָּוֹהִי וּקְרָא אַפִּיקוּ כָל אֱנַשׁ מֵעִלָּוָי וְלָא קָם אֱנַשׁ עִמֵּהּ כַּד אִתְיְדַע יוֹסֵף לְוַת אֲחוֹהִי:
@19 וִיהַב יָת קָלֵהּ בִּבְכִיתָא וּשְׁמָעוּ מִצְרַיִם וּשְׁמַע אֱנַשׁ בֵּית פַּרְעֹה:
@20 וַאֲמַר יוֹסֵף לַאֲחוֹהִי אֲנָא יוֹסֵף הַעַד כְּעַן אַבָּא קַיָּם וְלָא יָכִילוּ אֲחוֹהִי לַאֲתָבָא יָתֵהּ פִּתְגָּם ארֵי אִתְבְּהִילוּ מִן קֳדָמוֹהִי:
@21 וַאֲמַר יוֹסֵף לַאֲחוֹהִי קְרִיבוּ כְעַן לְוָתִי וּקְרִיבוּ וַאֲמַר אֲנָא יוֹסֵף אֲחוּכוֹן דִּי זַבִּנְתּוּן יָתִי לְמִצְרָיִם:
@22 וּכְעַן לָא תִתְנַסְסוּן וְלָא יִתְקָף בְּעֵינֵיכוֹן אֲרֵי זַבִּנְתּוּן יָתִי הַלְכָא אֲרֵי לְקַיָּמָא שַׁלְחַנִּי יְיָ קֳדָמֵיכוֹן:
@23 אֲרֵי דְנַן תַּרְתֵּין שְׁנִין כַּפְנָא בְּגוֹ אַרְעָא וְעוֹד חָמֵשׁ שְׁנִין דִּי לֵית זְרוֹעָא וַחֲצָדָא:
@24 וְשַׁלְחַנִּי יְיָ קֳדָמֵיכוֹן לְשַׁוָּאָה לְכוֹן שְׁאָרָא בְּאַרְעָא וּלְקַיָּמָא לְכוֹן לְשֵׁיזָבָא רַבָּא:
@25 וּכְעַן לָא אַתּוּן שְׁלַחְתּוּן יָתִי הַלְכָא אֶלָּהֵן מִן קֳדָם יְיָ וְשַׁוְּיַנִי לְאַבָּא לְפַרְעֹה וּלְרִבּוֹן לְכָל אֱנַשׁ בֵּיתֵהּ וְשַׁלִּיט בְּכָל אַרְעָא דְמִצְרָיִם:
@26 אוֹחוּ וּסְקוֹ לְוַת אַבָּא וְתֵימְרוּן לֵהּ כִּדְנַן אֲמַר בְּרָךְ יוֹסֵף שַׁוְּיַנִי יְיָ לְרִבּוֹן לְכָל מִצְרָיִם חוּת לְוָתִי לָא תִתְעַכָּב:
@27 וְתֵתֵב בְּאַרְעָא דְגשֶׁן וּתְהֵי קָרִיב לִי אַתְּ וּבְנָיךְ וּבְנֵי בְנָיךְ וְעָנָךְ וְתוֹרָךְ וְכָל דִּי לָךְ:
@28 וְאֵזוּן יָתָךְ תַּמָּן אֲרֵי עוֹד חֲמֵשׁ שְׁנִין כַּפְנָא דִּלְמָא תִתְמַסְכַּן אַתְּ וֶאֱנַשׁ בֵּיתָךְ וְכָל דִּי לָךְ:
@29 וְהָא עֵינֵיכוֹן חֲזָן וְעֵינֵי אָחִי בִנְיָמִין אֲרֵי בְלִישַׁנְכוֹן אֲנָא מְמַלֵּל עִמְּכוֹן:
@30 וּתְחַווּן לְאַבָּא יָת כָּל יְקָרִי בְּמִצְרַיִם וְיָת כָּל דִּי חֲזֵיתוּן וְתוֹחוּן וְתַחֲתוּן יָת אַבָּא הָכָא:
@31 וּנְפַל עַל צַוְּארֵי בִנְיָמִן אֲחוּהִי וּבְכָא וּבִנְיָמִן בְּכָא עַל צַוְּארֵהּ:
@32 וּנְשַׁק לְכָל אֲחוֹהִי וּבְכָא עֲלֵיהוֹן וּבָתַר כֵּן מַלִּילוּ אֲחוֹהִי עִמֵּהּ:
@33 וְקָלָא אִשְׁתְּמַע בֵית פַּרְעֹה לְמֵימַר עַלּוּ אֲחֵי יוֹסֵף וּשְׁפַר בְּעֵינֵי פַרְעֹה וּבְעֵינֵי עַבְדּוֹהִי:
@34 וַאֲמַר פַּרְעֹה לְיוֹסֵף אֱמַר לְאַחָיךְ דָּא עִיבִידוּ טְעוּנוּ יָת בְּעִירְכוֹן וֶאֱזִילוּ אוֹבִילוּ לְאַרְעָא דִּכְנָעַן:
@35 וּדְבָרוּ יָת אֲבוּכוֹן וְיָת אֱנַשׁ בָּתֵּיכוֹן וְעוּלוּ לְוָתִי וְאֶתֵּן לְכוֹן יָת טוּב אַרְעָא דְמִצְרַיִם וְתֵיכְלוּן יָת טוּבָא דְאַרְעָא:
@36 וְאַתְּ מְפַקָּדָא דָּא עִיבִידוּ סִיבוּ לְכוֹן מֵאַרְעָא דְמִצְרַיִם עֶגְלָן לְטַפְלֵּיכוֹן וְלִנְשֵׁיכוֹן וְתִטְּלוּן יָת אֲבוּכוֹן וְתֵיתוּן:
@37 וְעֵינְכוֹן לָא תְחוּס עַל מָנֵיכוֹן אֲרֵי טַב כָּל אַרְעָא דְמִצְרַיִם דִּלְכוֹן הוּא:
@38 וַעֲבָדוּ כֵן בְּנֵי יִשְׂרָאֵל וִיהַב לְהוֹן יוֹסֵף עֶגְלָן עַל מֵימַר פַּרְעֹה וִיהַב לְהוֹן זְוָדִין לְאָרְחָא:
@39 לְכָלְהוֹן יְהַב לִגְבַר אִצְטְלַּוָּן דִּלְבוּשִׁין וּלְבִנְיָמִן יְהַב תְּלַת מְאָה סִלְעִין דִּכְסַף וַחֲמֵשׁ אִצְטְלַוָּן דִּלְבוּשִׁין:
@40 וְלַאֲבוּהִי שְׁלַח כְּדָא עַסְרָא חֲמָרִין טְעִינִין מִטּוּבָא דְמִצְרָיִם וַעֲסַר אַתְנָן טְעִינָן עִיבוּר וּלְחֵם וּזְוָדִין לַאֲבוּהִי לְאָרְחָא:
@41 וְשַׁלַּח יָת אֲחוֹהִי וַאֲזָלוּ וַאֲמַר לְהוֹן לָא תִתְנַצוּן:בּאָ:רחָא:
@42 וּסְלִיקוּ מִמִּצְרָיִם וַאֲתוֹ לְאַרְעָא דִּכְנַעַן לְוַת יַעֲקֹב אֲבוּהוֹן:
@43 וְחַוִּיאוּ לֵהּ לְמֵימַר עַד כְּעַן יוֹסֵף קַיָּם וַאֲרֵי הוּא שַׁלִּיט בְּכָל אַרְעָא דְמִצְרָיִם וַהֲווֹ מִלַּיָּא פָּיְגָן עַל לִבֵּהּ אֲרֵי לָא הֵימִין לְהוֹן:
@44 וּמַלִּילוּ עִמֵּהּ יָת כָּל פִּתְגָּמֵי יוֹסֵף דִּי מַלִּיל עִמְּהוֹן וַחֲזָא יָת עֲגַלָּתָא דִּשְׁלַח יוֹסֵף לְמִטַּל יָתֵהּ וּשְׁרַת רוּחַ נְבוּאָה עַל יַעֲקֹב אֲבוּהוֹן:
@45 וַאֲמַר יִשְׂרָאֵל סַגִּי לִי חֶדְוָא עַד כְּעַן יוֹסֵף בְּרִי קַיָּם אֱזֵיל וְאֶחֱזִנֵּהּ עַד לָא אֵמוּת:
@46 וּנְטַל יִשְׂרָאֵל וְכָל דִּי לֵהּ וַאֲתָא לִבְאֵר שָׁבַע וּדְבַח דִּבְחִין לֵאלָהָא דְאֲבוּהִי יִצְחָק:
@47 וַאֲמַר יְיָ לְיִשְׂרָאֵל בְּחֶזְוֵי דְלֵילְיָא וַאֲמַר יַעֲקֹב יַעֲקֹב וַאֲמַר הָא אֲנָא:
@48 וַאֲמַר אֲנָא אֵל אֱלָהָא דְאָבוּךְ לָא תִדְחַל מִלְּמֵיחַת לְמִצְרַיִם אֲרֵי לְעַם סַגִּי אֲשֵׁוִּנָּךְ תַּמָּן:
@49 אֲנָא אֵחוֹת עִמָּךְ לְמִצְרַיִם וַאֲנָא אַסֵּקִנָּךְ אַף אַסָּקָא וְיוֹסֵף יְשַׁוֵּי יְדוֹהִי עַל עֵינָיךְ:
@50 וְקָם יַעֲקֹב מִבְּאֵרָא דְשָׁבַע וּנְטָלוּ בְנֵי יִשְׂרָאֵל יָת יַעֲקֹב אֲבוּהוֹן וְיָת טַפְלְהוֹן וְיָת נְשֵׁיהוֹן בַּעֲגַלְתָּא דִּי שְׁלַח פַּרְעֹה לְמִטַּל יָתֵהּ:
@51 וּדְבָרוּ יָת גֵּיתֵיהוֹן וְיָת קִנְיָנְהוֹן דִּי קְנוֹ בְּאַרְעָא דִּכְנַעַן וַאֲתוֹ לְמִצְרָיִם יַעֲקֹב וְכָל בְּנוֹהִי עִמֵּהּ:
@52 בְּנוֹהִי וּבְנֵי בְנוֹהִי עִמֵּהּ בְּנָתֵהּ וּבְנַת בְּנוֹהִי וְכָל זַרְעֵהּ אַיְתִי עִמֵּהּ לְמִצְרָיִם:
@53 וְאִלֵּין שְׁמָהַת בְּנֵי יִשְׂרָאֵל דְּעַלּוּ לְמִצְרַיִם יַעֲקֹב וּבְנוֹהִי בּוּכְרָא דְיַעֲקֹב רְאוּבֵן:
@54 וּבְנֵי רְאוּבֵן חֲנוֹךְ וּפַלּוּא וְחֶצְרֹן וְכַרְמִי:
@55 וּבְנֵי שִׁמְעוֹן יְמוּאֵל וְיָמִין וְאֹהַד וְיָכִין וְצֹחַר וְשָׁאוּל בַּר כְּנַעֲנֵיתָא:
@56 וּבְנֵי לֵוִי גֵּרְשׁוֹן קְהָת וּמְרָרִי:
@57 וּבְנֵי יְהוּדָה עֵר וְאוֹנָן וְשֵׁלָה וָפֶרֶץ וָזָרַח וּמִית עֵר וְאוֹנָן בְּאַרְעָא דִּכְנַעַן וַהֲווֹ בְנֵי פֶרֶץ חֶצְרֹן וְחָמוּל:
@58 וּבְנֵי יִשָּׂשכָר תּוֹלָע וּפֻוָּה וְיוֹב וְשִׁמְרוֹן:
@59 וּבְנֵי זְבֻלוּן סֶרֶד וְאֵלוֹן וְיַחְלְאֵל:
@60 אִלֵּין בְּנֵי לֵאָה דִּילִידַת לְיַעֲקֹב בְּפַדַּן אֲרָם וְיָת דִּינָה בְרַתֵּהּ כָּל נֶפֶשׁ בְּנוֹהִי וּבְנָתֵהּ תְּלָתִין וּתְלָת:
@61 וּבְנֵי גָד צִפְיוֹן וְחַגִּי שׁוּנִי וְאֶצְבּוֹן עֵרִי וַאֲרוֹדִי וְאַרְאֵלִי:
@62 וּבְנֵי אָשֵׁר יִמְנָה וְיִשְׁוָה וְיִשְׁוִי וּבְרִיעָה וְשֶׂרַח אֲחַתְהוֹן וּבְנֵי בְרִיעָה חֶבֶר וּמַלְכִּיאֵל:
@63 אִלֵּין בְּנֵי זִלְפָּה דִי יְהַב לָבָן לְלֵאָה בְרַתֵּהּ וִילִידַת יָת אִלֵּין לְיַעֲקֹב שִׁית עֶשְׂרֵי נַפְשָׁא:
@64 בְּנֵי רָחֵל אִתַּת יַעֲקֹב יוֹסֵף וּבִנְיָמִן:
@65 וְאִתְיְלִידוּ לְיוֹסֵף בְּאַרְעָא דְמִצְרַיִם דִּילִידַת לֵהּ אָסְנַת בַּת פּוֹטִי פֶרַע רַבָּא דְאוֹן יָת מְנַשֶּׁה וְיָת אֶפְרָיִם:
@66 וּבְנֵי בִנְיָמִן בֶּלַע וָבֶכֶר וְאַשְׁבֵּל גֵּרָא וְנַעֲמָן אֵחִי וָרֹאשׁ מֻפִּים וְחֻפִּים וָאָרְדְּ:
@67 אִלֵּין בְּנֵי רָחֵל דְּאִתְיְלִידוּ לְיַעֲקֹב כָּל נַפְשָׁא אַרְבָּעָה עֲשָׂר:
@68 וּבְנֵי דָן חֻשִׁים:
@69 וּבְנֵי נַפְתָּלִי יַחְצְאֵל וְגוּנִי וְיֵצֶר וְשִׁלֵּם:
@70 אִלֵּין בְּנֵי בִלְהָה דִּיהַב לָבָן לְרָחֵל בְּרַתֵּהּ וִילִידַת יָת אִלֵּין לְיַעֲקֹב כָּל נַפְשָׁא שִׁבְעָא:
@71 כָּל נַפְשָׁא דְּעַלָּא לְיַעֲקֹב לְמִצְרַיִם נָפְקֵי יַרְכֵּהּ בַּר מִנְּשֵׁי בְנֵי יַעֲקֹב כָּל נַפְשָׁתָא שִׁתִּין וְשִׁית:
@72 וּבְנֵי יוֹסֵף דִּי אִתְיְלִידוּ לֵהּ בְּמִצְרַיִם נַפְשָׁתָא תְרֵין כָּל נַפְשָׁתָא לְבֵית יַעֲקֹב דְּעַלּוּ לְמִצְרַיִם שִׁבְעִין:
@73 וְיָת יְהוּדָה שְׁלַח קֳדָמוֹהִי לְוַת יוֹסֵף לְפַנָּאָה קֳדָמוֹהִי לְגשֶׁן וַאֲתוֹ לְאַרְעָא דְגשֶׁן:
@74 וְטַקֵּיס יוֹסֵף רְתִכּוֹהִי וּסְלֵיק לְקַדָּמוּת יִשְׂרָאֵל אֲבוּהִי לְגשֶׁן וְאִתְגְּלִי לֵהּ וּנְפַל עַל צַוְארֵהּ וּבְכָא עַל צַוְארֵהּ עוֹד:
@75 וַאֲמַר יִשְׂרָאֵל לְיוֹסֵף אִלּוּ אֲנָא מָאִית זִמְנָא הָדָא מְנַחֵם אֲנָא בָּתַר דַּחֲזֵיתִי יָת אַפָיךְ אֲרֵי עַד כְּעַן אַתְּ קַיָּם:
@76 וַאֲמַר יוֹסֵף לַאֲחוֹהִי וּלְבֵית אֲבוּהִי אֶסַּק וְאֵחַוֵּי לְפַרְעֹה וְאֵימַר לֵהּ אַחַי וּבֵית אַבָּא דִּי בְאַרְעָא דִּכְנַעַן עַלּוּ לְוָתִי:
@77 וְגֻּבְרַיָּא רָעֵי עָנָא אֲרֵי גֻּבְרֵי מָרֵי גֵּיתֵי הֲווֹ וְעָנְהוֹן וְתוֹרְהוֹן וְכָל דִּי לְהוֹן אַיְתִיאוּ:
@78 וִיהֵי אֲרֵי יִקְרֵי לְכוֹן פַּרְעֹה וְיֵימַר מָה עוֹבָדֵיכוֹן:
@79 וְתֵימְרוּן גֻּבְרֵי מָרֵי גֵּיתֵי הֲווֹ עַבְדָּיךְ מֵעוּלֵמָנָא וְעַד כְּעַן אַף אֲנַחְנָא אַף אַבְהָתָנָא בְּדִיל דִּי תֵיתְבוּן בְּאַרְעָא דְגשֶׁן אֲרֵי מְרַחֲקִין מִצְרָאֵי כָּל רָעֵי עָנָא:
@80 וַאֲתָא יוֹסֵף וְחַוִּי לְפַרְעֹה וַאֲמַר אַבָּא וְאַחַי וְעָנְהוֹן וְתוֹרְהוֹן וְכָל דִּי לְהוֹן אֲתוֹ מֵאַרְעָא דִּכְנָעַן וְהָא אִנּוּן בְּאַרְעָא דְגשֶׁן:
@81 וּמִקְצַת מִן אֲחוֹהִי דְּבַר חַמְשָׁא גֻּבְרִין וַאֲקֵימִנּוּן קֳדָם פַּרְעֹה:
@82 וַאֲמַר פַּרְעֹה לַאֲחוֹהִי מָה עוֹבָדֵיכוֹן וַאֲמָרוּ לְפַרְעֹה רָעֵי עָנָא עַבְדָּיךְ אַף אֲנַחְנָא אַף אֲבָהָתָנָא:
@83 וַאֲמָרוּ לְוַת פַּרְעֹה לְאִתּוֹתָבָא בְאַרְעָא אֲתֵינָא אֲרֵי לֵית רַעֲיָא לְעָנָא דִּי לְעַבְדָּיךְ אֲרֵי תַקִּיף כַּפְנָא בְּאַרְעָא דִּכְנָעַן וּכְעַן יֵתְבוּן כְּעַן עַבְדָּיךְ בְּאַרְעָא דְגשֶׁן:
@84 וַאֲמַר פַּרְעֹה לְיוֹסֵף לְמֵימָר אֲבוּךְ וְאַחָיךְ אֲתוֹ לְוָתָךְ:
@85 אַרְעָא דְמִצְרַיִם קֳדָמָךְ הִיא בִּדְשַׁפִּיר בְּאַרְעָא אוֹתֵיב יָת אֲבוּךְ וְיָת אַחָיךְ יֵתְבוּן בְּאַרְעָא דְגשֶׁן וְאִם יָדַעְתְּ וְאִית בְּהוֹן גֻּבְרִין דְּחֵילָא וּתְמַנִּנוּן רַבָּנֵי גֵיתֵי עַל דִּי לִי:
@86 וְאַיְתִי יוֹסֵף יָת יַעֲקֹב אֲבוּהִי וַאֲקִימִנֵּהּ קֳדָם פַּרְעֹה וּבְרִיךְ יַעֲקֹב יָת פַּרְעֹה:
@87 וַאֲמַר פַּרְעֹה לְּיַעֲקֹב כַּמָּה יוֹמֵי שְׁנֵי חַיָּיךְ:
@88 וַאֲמַר יַעֲקֹב לְפַרְעֹה יוֹמֵי שְׁנֵי תוֹתָבוּתַי מְאָה וּתְלָתִין שְׁנִין זְעֵירִין וּבִישִׁין הֲווֹ יוֹמֵי שְׁנֵי חַיַּי וְלָא אַדְבִּיקוּ יָת יוֹמֵי שְׁנֵי חַיֵּי אֲבָהָתַי בְּיוֹמֵי תּוֹתָבוּתְהוֹן:
@89 וּבָרִיךְ יַעֲקֹב יָת פַּרְעֹה וּנְפַק מִן קֳדָם פַּרְעֹה:
@90 וְאוֹתֵיב יוֹסֵף יָת אֲבוּהִי וְיָת אֲחוֹהִי וִיהַב לְהוֹן אַחֲסָנָא בְּאַרְעָא דְמִצְרַיִם בִּדְשַׁפִּיר בְּאַרְעָא בְּאַרְעָא דְרַעְמְסֵס כְּמָא דִי פַקֵּיד פַרְעֹה:
@91 וְזָן יוֹסֵף יָת אֲבוּהִי וְיָת אֲחוֹהִי וְיָת כָּל בֵּית אֲבוּהִי לַחְמָא לְפוּם טַפְלָא:
@92 וְלַחֲמָא לֵית בְּכָל אַרְעָא אֲרֵי תַקִּיף כַּפְנָא לַחֲדָא וְאִשְׁתַּלְהֵי עַמָּא דְאַרְעָא דְמִצְרַיִם וְעַמָּא דְאַרְעָא דִּכְנַעַן מִן קֳדָם כַּפְנָא:
@93 וְלַקִּיט יוֹסֵף יָת כָּל כַּסְפָּא דְּאִשְׁתְּכַח בְּאַרְעָא דְמִצְרַיִם וּבְאַרְעָא דִּכְנַעַן בְּעִיבוּרָא דִּי אִנּוּן זָבְנִין וְאַיְתִי יוֹסֵף יָת כַּסְפָּא לְבֵית פַּרְעֹה:
@94 וּשְׁלִים כַּסְפָא מֵאַרְעָא דְמִצְרַיִם וּמֵאַרְעָא דִּכְנַעַן וַאֲתוֹ כָּל מִצְרָאֵי לְוַת יוֹםֵף לְמֵימַר הַב לָנָא לַחֲמָא וּלְמָה נְמוּת לְקִבְלָךְ אֲרֵי שְׁלִים כַּסְפָּא:
@95 וַאֲמַר יוֹסֵף הָבוּ גֵּיתֵיכוֹן וְאֶתֵּן לְכוֹן בְּגֵּיתֵיכוֹן אִם שְׁלִים כַּסְפָּא:
@96 וְאַיְתִיּוּ יָת גֵּיתֵיהוֹן לְוַת יוֹסֵף וִיהַב לְהוֹן יוֹסֵף לַחְמָא בְּסוּסְוָתָא וּבְגֵיתֵי עָנָא וּבְגֵיתֵי תוֹרִין וּבַחֲמָרִין וְזָנִנּוּן בְּלַחֲמָא בְּכָל גֵּיתֵיהוֹן בְּשַׁתָּא הַהִיא:
@97 וּשְׁלִימַת שַׁתָּא הַהִיא וַאֲתוֹ לְוָתֵהּ בְּשַׁתָּא תִנְיֵתָא וַאֲמָרוּ לֵהּ לָא נְכַסֵּי מִן רִבּוֹנִי אֶלָּהֵין שְׁלִים כַּסְפָּא וְגֵּיתֵי בְעִירָא לְוַת רִבּוֹנִי לָא אִשְׁתָּאַר קֳדָם רִבּוֹנִי אֶלָּהֵין גְּוִיָתָנָא וְאַרְעָנָא:
@98 לְמָה נְמוּת לְעֵינָיךְ אַף אֲנַחְנָא אַף אַרְעָתָנָא קְנֵי יָתָנָא וְיָת אַרְעָתָנָא בְּלַחְמָא וּנְהֵי אֲנַחְנָא וְאַרְעָתָנָא עַבְדִּין לְפַרְעֹה וְהַב בַּר זַרְעָא וְנֵיחֵי וְלָא נְמוּת וְאַרְעָא לָא תְבוּר:
@99 וּקְנָא יוֹסֵף יָת כָּל אַרְעָא דְמִצְרַיִם לְפַרְעֹה אֲרֵי זַבִּינוּ מִצְרַיִם גְּבַר חַקְלֵהּ אֲרֵי תְקֵיף עֲלֵיהוֹן כַּפְנָא וַהֲוַת אַרְעָא לְפַרְעֹה:
@100 וְיָת עַמָּא אַעְבֵּר יָתֵהּ מִקְּרֵי לִקְרֵי מִסְּיָפֵי תְּחוּם מִצְרַיִם וְעַד סוֹפֵהּ:
@101 לְחוֹד אַרְעָא דְכֻמָּרַיָּא לָא זַבִּין אֲרֵי חֳלָקָא לְכֻמָּרַיָּא מִלְּוַת פַּרְעֹה וְאָכְלִין יָת חֳלָקְהוֹן דִּי יְהַב לְהוֹן פַּרְעֹה עַל כֵּן לָא זַבִּינוּ יָת אַרְעֲהוֹן:
@102 וַאֲמַר יוֹסֵף לְעַמָּא הָא זְבֵנִית יָתְכוֹן יוֹמָא דֵּין וְיָת אַרְעֲכוֹן לְפַרְעֹה הֵא לְכוֹן בַּר זַרְעָא וְתִזְרְעוּן יָת אַרְעָא:
@103 וִיהֵי בְּאָעוֹלֵי עֲלַלְתָּא וְתִתְּנוּן חַד מִן חַמְשָׁא לְפַרְעֹה וְאַרְבַּע חֳלָקִין יְהֵא לְכוֹן לְבַר זְרַע חַקְלָא וּלְמֵיכַלְכוֹן וְלֶאֱנַשׁ בָתֵּיכוֹן וּלְמֵיכַל לְטַפְלְכוֹן:
@104 וַאֲמָרוּ קַיִּמְתָּנָא נִשְׁכַּח רַחֲמִין בְּעֵינֵי רִבּוֹנִי וּנְהֵי עַבְדִּין לְפַרְעֹה:
@105 וְשַׁוִּי יָתַהּ יוֹסֵף לִגְזֵרָא עַד יוֹמָא הָדֵין עַל אַרְעָא דְמִצְרַיִם דִּיהוֹן יָהֲבִין חַד מִן חַמְשָׁא לְפַרְעֹה לְחוֹד אַרְעָא דְכֻמָּרַיָּא בִּלְחוֹדֵיהוֹן לָא הֲוַת לְפַרְעֹה:
@106 וִיתֵיב יִשְׂרָאֵל בְּאַרְעָא דְמִצְרַיִם בְּאַרְעָא דְגשֶׁן וְאַחֲסִינוּ בַהּ וּנְפִישׁוּ וּסְגִיאוּ לַחֲדָא:

@1 **ויגש אליו. דבר באזני אדני.** (בראשית רבה) יכנסו דברי באזניך: **ואל יחר אפך.** מכאן אתה למד שדבר אליו קשות: **כי כמוך כפרעה.** חשוב אתה בעיני כמלך, זהו פשוטו. ומדרשו - סופך ללקות עליו בצרעת כמו שלקה פרעה ע"י זקנתי שרה על לילה אחת שעכבה (בראשית רבה). דבר אחר מה פרעה גוזר ואינו מקיים מבטיח ואינו עושה אף אתה כן. וכי זוהי שימת עין שאמרה לשים עיניך עליו, דבר אחר: כי כמוך כפרעה - אם תקניטני אהרוג אותך ואת אדוניך (בראשית רבה):
@2 **אדני שאל את עבדיו.** (בראשית רבה) בתחילה בעלילה באת עלינו, למה היה לך לשאול כל אלה, ביתך היינו מבקשים, או אחותינו אתה מבקש, ואף על פי כן ונאמר אל אדוני לא כחדנו ממך דבר:
@3 **ואחיו מת.** מפני היראה היה מוציא דבר שקר מפיו, אמר - אם אומר לו שהוא קיים - ימר הביאוהו אצלי: **לבדו לאמו.** מאותו האם אין לו עוד אח:
@5 **ועזב את אביו ומת.** אם יעזוב את אביו דואגים אנו שמא ימות בדרך שהרי אמו בדרך מתה:
@12 **וקראו אסון.** (בראשית רבה) שהשטן מקטרג בשעת הסכנה: **והורדתם את שיבתי וגו'.** עכשיו כשהוא אצלי אני מתנחם בו על אמו ועל אחיו, ואם ימות זה דומה עלי ששלשתן מתו ביום:
@14 **והיה כראותו כי אין הנער ומת.** אביו מצרתו:
@15 **כי עבדך ערב את הנער.** אם תאמר למה אני נכנס לתגר יותר משאר אחי - הם כולם מבחוץ ואני נתקשרתי בקשר חזק להיות מנודה בשני עולמות:
@16 **ישב נא עבדך וגו'.** (בראשית רבה) לכל דבר אני מעולה ממנו, לגבורה, ולמלחמה, ולשמש:
@18 **ולא יכול יוסף להתאפק לכל הנצבים.** לא היה יכול לסבול שיהיו מצרים נצבים עליו ושומעים שאחיו מתביישים בהודעו להם:
@19 **וישמע בית פרעה.** ביתו של פרעה כלומר עבדיו ובני ביתו ואין זה לשון בית ממש אלא כמו בית ישראל. בית יהודה [מישנד"ה בלעז]:
@20 **נבהלו מפניו.** וכמוהו הבושה:
@21 **גשו נא אלי.** ראה אותם נסוגים לאחור, אמר עכשיו אחי נכלמים, קרא להם בלשון רכה ותחנונים והראה להם שהוא מהול (בראשית רבה):
@22 **למחיה.** להיות לכם למחיה:
@23 **כי זה שנתיים הרעב.** עברו משני הרעב:
@25 **לאב.** לחבר ולפטרון [צום בשיטצער. פאטראן בלעז ???]: **ועלו אל אבי.** ארץ ישראל גבוה מכל הארצות:
@28 **פן תורש.** דלמא תתמסכן, לשון מוריש ומעשיר:
@29 **והנה עיניכם רואות.** בכבודי ושאני אחיכם ושאני מהול ככם. ועוד כי פי המדבר אליכם בלשון הקודש (בבראשית רבה): **ועיני אחי בנימין.** (מגילה יז) השוה את כולם יחד לומר שכשם שאין לי שנאה על בנימין אחי שהרי לא היה במכירתי, כך אין בלבי שנאה עליכם:
@31 **ויפל על צוארי בנימין אחיו ויבך.** על שני מקדשות שעתידים להיות בחלקו של בנימין וסופן להיחרב:
@32 **ואחרי כן.** מאחר שראוהו בוכה ולבו שלם עמהם: דברו אחיו אתו. שמתחילה היו בושים ממנו:
@33 **והקול נשמע בית פרעה.** כמו בבית פרעה וזהו לשון בית ממש:
@34 **טענו את בעירכם.** תבואה:
@35 **ואת טוב ארץ מצרים.** ארץ גושן. ניבא ואינו יודע מה ניבא, סופה לעשותה כמצולה שאין בה דגים: **חלב הארץ.** כל חלב לשון מיטב הוא:
@36 **ואתה צויתה.** מפי לומר להם: **זאת עשו.** כך אמור להם שברשותי הוא:
@40 **שלח כזאת.** כחשבון הזה ומהו החשבון י' חמורים וגו'. (רצונו שמלת כזאת המיותרת ובכ''ף הדמיון מורה על כי מעולם לא שלח לו י' חמורים וי' אתונות, רק הכי קאמר קרא. בשם הגאון מהרש"ל): **מטוב מצרים.** מצינו בגמרא ששלח לו יין ישן שדעת זקנים נוחה הימנו. ומדרש אגדה גריסין של פול: **בר ולחם.** כתרגומו: **ומזון.** לפתן (כך גירסאת רא"ם):
@41 **אל תרגזו בדרך.** אל תתעסקו בדבר הלכה שלא תרגז עליכם הדרך. דבר אחר - אל תפסעו פסיעה גסה ותכנסו בחימה לעיר, ולפי פשוטו של מקרא יש לומר - לפי שהיו נכלמים - היה דואג שמא יריבו בדרך על דבר מכירתו להתווכח זה עם זה ולומר על ידך נמכר, אתה ספרת לשון הרע עליו וגרמת לנו לשנאתו:
@43 **וכי הוא מושל.** ואשר הוא מושל: **ויפג לבו.** נחלף לבו והלך מלהאמין, לא היה לבו פונה אל הדברים, לשון מפיגין טעמן בלשון משנה וכמו (איכה ג) מאין הפוגות (ירמיה מח ???) וריחו לא נמר מתרגמינן וריחיא לא פג:
@44 **את כל דברי יוסף.** סימן מסר להם במה שהיה עוסק כשפירש ממנו בפרשת עגלה ערופה, זהו שנאמר וירא את העגלות אשר שלח יוסף ולא נאמר אשר שלח פרעה: **ותחי רוח יעקב.** שרתה עליו שכינה שפירשה ממנו:
@45 **רב עוד.** רב לי עוד שמחה וחדוה הואיל ועוד יוסף בני חי:
@46 **בארה שבע.** כמו לבאר שבע, ה"א בסוף תיבה במקום למ"ד בתחילתה: **לאלוהי אביו יצחק.** חייב אדם בכבוד אביו יותר מבכבוד זקנו לפיכך תלה ביצחק ולא באברהם:
@47 **יעקב יעקב.** לשון חיבה:
@48 **אל תירא מרדה מצרימה.** לפי שהיה מיצר על שנזקק לצאת לחוצה לארץ:
@49 **ואנכי אעלך.** הבטיחו להיות נקבר בארץ:
@51 **אשר רכשו בארץ כנען.** אבל מה שרכש בפדן ארם נתן הכל לעשו בשביל חלקו במערת המכפלה, אמר נכסי חוצה לארץ אינן כדאי לי וזהו אשר כריתי לי, העמיד לו צבורין של זהב וכסף כמין כרי ואמר לו טול את אלו:
@52 **ובנות בניו.** סרח בת אשר, ויוכבד בת לוי:
@53 **הבאים מצרימה.** על שם השעה קורא להם הכתוב באים. ואין לתמוה על אשר לא כתב אשר באו:
@55 **בן הכנענית.** בן דינה שנבעלה לכנעני ,כשהרגו את שכם לא הייתה דינה רוצה לצאת עד שנשבע לה שמעון שישאנה (בראשית רבה):
@60 **אלה בני לאה ואת דינה בתו.** הזכרים תלה בלאה והנקבות תלה ביעקב ללמדך אשה מזרעת תחלה יולדת זכר, איש מזריע תחלה יולדת נקבה: **שלשים ושלש.** ובפרטן אי אתה מוצא אלא שלשים ושנים, אלא זו יוכבד שנולדה בין החומות בכניסתן לעיר שנאמר אשר ילדה אותה ללוי במצרים, לידתה במצרים ואין הורתה במצרים:
@64 **בני רחל אשת יעקב.** ובכולן לא נאמר בהן אשת אלא שהיתה עיקרו של בית:
@71 **כל הנפש הבאה ליעקב.** שיצאו מארץ כנען לבוא למצרים. ואין הבאה זו לשון עבר, אלא לשון הווה, כמו (אסתר ב) בערב היא באה וכמו והנה רחל בתו באה עם הצאן, לפיכך טעמו למטה באל"ף, לפי שכשיצאו לבוא מארץ כנען לא היו אלא שישים ושש. והשני כל הנפש לבית יעקב הבאה מצרימה שבעים הוא לשון עבר לפיכך טעמו למעלה בבי"ת לפי שמשבאו שם היו שבעים שמצאו שם יוסף ושני בניו ונתוספה להם יוכבד בין החומות. (ועיין בביאור לת"י ומשם תמצא להרוות צמאונך ברש"י) ולדברי האומר תאומות נולדו עם השבטים צריכים אנו לומר שמתו לפני ירידתן למצרים שהרי לא נמנו כאן. מצאתי בויקרא רבה עשו שש נפשות היו לו והכתוב קורא אותן נפשות ביתו לשון רבים, לפי שהיו עובדין לאלהות הרבה, יעקב שבעים היו לו והכתוב קורא אותן נפש, לפי שהיו עובדים לאל אחד:
@73 **להורות לפניו.** כתרגומו לפנות לו מקום ולהורות האיך יתיישב בה: **לפניו.** קודם שיגיע לשם.ומדרש אגדה: להורות לפניו לתקן לו בית תלמוד שמשם תצא הוראה:
@74 **ויאסור יוסף מרכבתו.** הוא עצמו אסר את הסוסים למרכבה להזדרז לכבוד אביו: **וירא אליו.** יוסף נראה אל אביו: **ויבך על צואריו עוד.** לשון הרבות בכיה. וכן (איוב לד) כי לא על איש ישים, עוד לשון רבוי הוא, אינו שם עליו עלילות נוספות על חטאיו, אף כאן הרבה והוסיף בבכי יותר על הרגיל אבל יעקב לא נפל על צוארי יוסף ולא נשקו. ואמרו רבותינו שהיה קורא את שמע:
@75 **אמותה הפעם.** פשוטו כתרגומו ומדרשו - סבור הייתי למות שתי מיתות בעולם הזה ובעולם הבא, שנסתלקה שכינה ממני, והייתי אומר שיתבעני הקב"ה מיתתך, עכשיו שעודך חי לא אמות אלא פעם אחת:
@76 **ואמרה אליו אחי וגו'.** ועוד אומר לו (פסוק לב) והאנשים רועי צאן וגו':
@79 **בעבור תשבו בארץ גשן.** והיא צריכה לכם שהיא ארץ מרעה, וכשתאמרו לו שאין אתם בקיאין במלאכה אחרת ירחיקכם מעליו ויושיבכם שם: **כי תועבת מצרים וגו'.** לפי שהם להם אלהות.
@81 **ומקצה אחיו.** מן הפחותים שבהם לגבורה שאין נראים גיבורים, שאם יראה אותם גיבורים יעשה אותם אנשי מלחמתו. ואלה הם ראובן שמעון לוי יששכר ובנימין, אותם שלא כפל משה שמותם כשברכם, אבל שמות הגיבורים כפל, וזאת ליהודה שמע ה' קול יהודה, ולגד אמר ברוך מרחיב גד. ולנפתלי אמר נפתלי. ולדן אמר דן. וכן לזבולן, וכן לאשר זה לשון בראשית רבה שהיא אגדת ארץ ישראל אבל בגמרא בבלית שלנו (בבא קמא צ''ב) מצינו שאותם שכפל משה שמותם הם החלשים ואותן הביא לפני פרעה, ויהודה שהוכפל שמו לא הוכפל משום חלשות, אלא טעם יש בדבר כדאיתא בבבא קמא ובברייתא דספרי שנינו בה בוזאת הברכה כמו בגמרא שלנו:
@85 **אנשי חיל.** בקיאין באומנותן לרעות צאן: **על אשר לי.** על צאן שלי:
@86 **ויברך יעקב.** היא שאילת שלום כדרך כל הנראים לפני המלכים לפרקים, שלידי"ר בלע"ז [גריסען]:
@88 **שני מגורי.** ימי גרותי כל ימי הייתי גר בארץ: **ולא השיגו.** בטובה:
@89 **ויברך יעקב.** כדרך כל הנפטרים מלפני שרים מברכים אותם ונוטלים רשות ומה ברכה ברכו שיעלה נילוס לרגליו לפי שאין מצרים שותה מי גשמים אלא נילוס עולה ומשקה ומברכתו של יעקב ואילך היה פרעה בא אל נילוס והוא עולה לקראתו ומשקה את הארץ [תנחומא]:
@90 **רעמסס.** מארץ גושן היא:
@91 **לפי הטף.** לפי הצריך לכל בני ביתם:
@92 **ולחם אין בכל הארץ.** חוזר לענין הראשון לתחלת שני הרעב: **ותלה.** כמו ותלאה לשון עייפות כתרגומו ודומה לו (משלי כו) כמתלהלה היורה זיקים:
@94 **אפס.** כתרגומו שלים:
@97 **בשנה השנית.** שנית לשני הרעב: **כי אם תם הכסף וגו'.** כי אשר תם הכסף והמקנה ובא הכל אל יד אדוני: **בלתי אם גויתנו.** כמו אם לא גויתנו:
@98 **ותן זרע.** לזרוע האדמה ואע"פ שאמר יוסף ועוד חמש שנים אשר אין חריש וקציר מכיון שבא יעקב למצרים באה ברכה לרגליו והתחילו לזרוע וכלה הרעב וכן שנינו בתוספתא דסוטה: **לא תשם - לא תהא שממה.** לא תבור לשון שדה בור שאינו חרוש:
@99 **ותהי הארץ לפרעה.** קנויה לו:
@100 **ואת העם העביר.** יוסף מעיר לעיר לזכרון שאין להם עוד חלק בארץ והושיב של עיר זו בחברתה, ולא הוצרך הכתוב לכתוב זאת אלא להודיעך שבחו של יוסף שנתכוין להסיר חרפה מעל אחיו שלא יהיו קורין אותם גולים (חולין ס): **מקצה גבול מצרים וגו'.** כן עשה לכל הערים אשר במלכות מצרים מקצה גבולה ועד קצה גבולה:
@101 **הכהנים.** הכומרים כל לשון כהן משרת לאלהות הוא חוץ מאותן שהם לשון גדולה כמו כהן מדין כהן און: **חוק לכהנים.** חק כך וכך לחם ליום:
@102 **הא.** כמו הנה כמו (יחזקאל טז) וגם אני הא דרכך בראש נתתי:
@104 **נמצא חן.** לעשות לנו זאת כמו שאמרת: **והיינו עבדים לפרעה.** להעלות לו המס הזה בכל שנה לחק שלא יעבור:
@106 **וישב ישראל בארץ מצרים.** והיכן בארץ גושן שהיא מארץ מצרים: **ויאחזו בה.** לשון אחוזה:

@1 **ידבר נא עבדך דבר** . לאמר כי דברים מועטים ידבר לא יהיו עליו לטורח והנכון בעיני כי "דבר" הוא התמורה אשר יחלה פניו להחליף בנימין אחיו בו כי לא יבקש ממנו דבר אחר ושאר דבריו פיוס ובקשה לזה
@1 "ואל יחר אפך בעבדך" - יאמר אל יחר אפך בי על דברי לפניך
@1 "כי כמוך כפרעה" - ובמורא גדול אני מדבר לפניך כאלו אני מדבר לפני פרעה
@2 **אדני שאל את עבדיו** . לא ידעתי טעם לאריכות דברי יהודה בספור מה שהיה כבר ביניהם ומה שאמרו רז"ל (ב"ר צג ו) וכי זו היא שימת עין שאמרת לשום עינך עליו אינה טענה כי המושל שיצוה להביא אדם לפניו לא יעשה על מנת לפטור אותו מן הרעות שיעשה וכל שכן על הגנבה שיגנוב מבית המלך הגביע אשר ישתה בו ומתחלה כבר שם עינו עליו לטובה וקרא לו שלום בדבר אלהים יחנך בני (לעיל מג כט) ועשה לכולם לכבודו משתה לפניו בבית המלכות והרבה משאות להם ונתן להם בר כאשר יוכלון שאת יותר מן הכסף שהביאו לו כאשר פירשתי (לעיל מד א) ומה לעשות לו ואשר יראה לי על דרך הפשט שאינם רק תחנונים להעיר רחמיו כי חשב יהודה כי האלהים הוא ירא כאשר אמר לו וכאשר נהג עמהם חמלה כירא חטא לנחם אותם על הצער שעשה להם (לעיל מג כג) וזה ענין הסיפור אמר לו אנחנו באונס הגדנו באחינו זה מפני שאלת אדני ולא הודינו גם כן להורידו לפניך כמצותך הראשונה רק אמרנו כי לא יוכל הנער לעזוב את אביו אבל בנפשינו נביא אותו מפני זלעפות רעב כי אמרת לא תוסיפון לראות פני לא רצה אבינו לשמוע עד היותינו כולנו בסכנה לשוב לשבר מעט אכל ואז הודה בפחד ובדאגה ועתה כראותו כי אין הנער ימות בנפש מרה ולכן תפול נא תחנתי לפניך לרחם עלינו ועל הזקן וקח אותי תחת הנער לעבד עולם כי טוב אני ממנו ולך תהיה צדקה וזה טעם כל הפרשה ויתכן שיהיה והורידו עבדיך את שיבת עבדך אבינו כנוי לכבוד והורדת את שיבת עבדך אבינו וכן וחטאת עמך (שמות ה טז) ויש לומר עוד על דרך רבותינו שאמרו זו היא השמת עין יאמר כי כמוך כפרעה ראוי שתעמד בדבורך ובתיורך כי על פיך הבאנו אותו באונס גדול כאשר יזכיר ופחד לפרש לו יותר אבל יש בסתר דבריו שהיה מעשה הגביע תחבולה מאתו להעלילם כי למה יבקש לראותו על כרחם וכך אמרו בבראשית רבה (צג ח) אמר לו יהודה תדע לך שבעלילה באת עלינו כמה מדינות ירדו ליקח אוכל כלום שאלת אותם כמו ששאלת לנו שמא בתך אנו מבקשים או אחותנו אתה מבקש יאמרו כי זה היה נרמז בדבריו
@4 **ואשימה עיני עליו** . אמר רבי אברהם הטעם שאראה אותו ולא מצאתי בכתוב שימת עין על הראיה בלבד ושמתי עיני עליהם לטובה (ירמיהו כד ו) קחנו ועינך שים עליו ואל תעש לו מאומה רע (שם לט יב) כי לא צוה אותו שיראנו אחר שיקחנו אלא שישמור אותו ויטיב לו אבל נדר להם יוסף לחמול עליו ולשמרו ואם לא נזכר בפירוש כאשר יקצר שם בכל הדברים האלה אשר ספר יהודה בפניו ולא הזכיר מאסר שמעון ועלילת מרגלים אתם דרך מוסר או אימת מלכות
@5 **ועזב את אביו ומת** . פירש רבי אברהם ומת אביו ואם כן היה אומר לא יוכל אבינו לעזוב את בנו ועזב את בנו ומת או לא נוכל שיעזוב הנער את אביו כי לא יתלו החמלה על אביהם בנער כי הם יחזיקוהו כילד לא ידע בין טוב לרע אבל פירוש לא יוכל הנער לעזוב את אביו מפני נערותו והיותו ילד שעשועים בחיק אביו אשר אהבו ואם יעזבנו ויבא בדרך ימות הנער
@7 **כי עלינו אל עבדך אבי ונגד לו את דברי אדני** . אמר כי בבואם אליו מיד הגידו לו שלא יוסיפו לראות פניו בלא אחיהם הקטן ולא אבה לשלחו והיה מניח לו שמעון במאסרו וזה טעם ויאמר אבינו שובו שברו לנו מעט אוכל כי לא רצה להודות לשלחו בכל אשר אמרנו עד שדחקו הרעב
@10 **אתם ידעתם כי שנים ילדה לי אשתי** . אם יאמר שהוא יחיד לאמו מה טעם בזה שתרד שיבתו ברעה שאולה אחרי שיש לו כמה בנים רבים ובני בנים ואמו כבר מתה לא תבכה עליו בפניו אבל הטעם כי יעקב לא לקח אשה מדעתו רק רחל וזה טעם ילדה לי "אשתי" כי לא נולדו לי מאשה אשר היא אשתי ברצוני רק שנים ושמתי אהבתי בהם כאלו הם יחידים לי והשאר כבני פילגשים הם אלי ואחיו מת וזה לבדו בני יחידי אשר אהבתי ולכן יקדים הכתוב רחל ללאה כרחל וכלאה אשר בנו שתיהם את בית ישראל (רות ד יא) ויקרא לרחל וללאה השדה (לעיל לא ד) כי היא הקודמת במחשבתו ואמרו המפרשים כי לכך יאמר בסדר הזה (להלן מו יט) בני רחל אשת יעקב כי היא תקרא אשתו באמת בלא מרמה ולדעתי היה זה מפני שהזכירה שם בין השפחות וכבר הזכרתי כן (לעיל לא לג)
@12 **וקרהו אסון והורדתם את שיבתי** . אם יקראהו אסון כאחיו תורידו את שיבתי ברעה שאולה או וקרהו אסון שיקרנו כן מפני היותו נער ורך ולא נסה ללכת בדרך וכמו שאמר למעלה (מב ד) פן יקראנו אסון כי פירוש אסון מות מקרית כמתים בידי אדם וחיה רעה או בשנוי האויר בדרך
@15 **כי עבדך ערב את הנער** . יאמר כי ירד ביגון שאולה עליו כי גם בכל זה שאמרנו לו לא רצה הזקן לשלחו עד שנעשיתי לו ערב עליו ובטח בי ועל כן ישב נא עבדך תחתיו ואם יהיה פירוש "והורידו עבדיך" כפשוטו יאמר אנחנו הגורמים מיתת הזקן ברעה כי אני ערבתי בו
@17 **ואמר כי איך אעלה אל אבי** . להודיעו כי יבחר להיות עבד עולם מעלותו אל אביו בלתי הנער שלא יוכל לראות ברעתו כי יבכה תמיד ויתאונן עליו כל היום והזכיר זה שלא יחשוד אותו שיעשה מרמה בעבור שהוא ידע לברוח יותר מן הנער
@18 **ולא יכל יוסף להתאפק לכל הנצבים עליו** . לא יכול לסבול שיהיו המצריים נצבים עליו ושומעין שאחיו מתביישין בהודעו להם לשון רש"י ורבי אברהם אמר להתאפק לסבול לכל הנצבים עליו טעמו עד שיצאו כל הנצבים עליו והוצרך לקרא להוציאם אבל אונקלוס תרגם לאתחסנא להתחזק וכן ואתאפק ואעלה העולה (שמואל א יג יב) וכן כל לשון התאפקות בכל מקום חזוק והנכון בעיני שהיו שם מבית פרעה ומן המצרים אנשים רבים יחלו פניו למחול לבנימין כי נכמרו רחמיהם על תחנוני יהודה ולא יכול יוסף להתחזק לכלם ויקרא לעבדיו הוציאו כל איש נכרי מעלי כי אדבר עמהם ויצאו מעליו ובצאתם מעליו נתן את קולו בבכי וישמעו מצרים ואנשי בית פרעה המוצאים מעליו כי עודם בחצר החיצונה ויתכן כי פירוש "הנצבים עליו" משרתיו העומדים לפניו כמו הנער הנצב על הקוצרים (רות ב ו) שרי הנצבים (מלכים א ה ל) להתיצב על ה' (איוב א ו) וטעם "ויקרא" שהרים קולו בכעס ואמר למשרתיו הוציאו כל איש מעלי בלתי האנשים האלה וטעם בהוצאה שהוציאם משם כדי שלא ישמעו בהזכירו להם המכירה כי תהיה להם (לחרפה) וגם אליו למכשול שיאמרו עבדי פרעה ומצרים עליהם אלו אנשי בוגדות לא יגורו בארצנו ולא ידרכו בארמנותינו בגדו באחיהם גם באביהם בגדו מה יעשו במלך ובעמו וגם ביוסף לא יאמינו עוד
@23 **כי זה שנתים הרעב בקרב הארץ** . הזכיר להם מה שעבר וידעו גם הם לומר כי הארץ אשר עברו עליה שתי שנים ברעב ואכלו כל מה שהיה בידם ונתיקר השער מאד ועוד יעברו עליהם חמש שנים לא תהיה לכם בה מחיה כלל אם לא שלחני השם לפניכם
@27 **וישבת בארץ גשן** . היה יוסף יודע באביו שלא ירצה לעמוד בארץ מצרים אשר שם הבירה למלכות על כן שלח לו מעתה כי בארץ גושן יושיבנו וטעם אתה ובניך מחובר בפסוק העליון רדה אלי אתה ובניך ובני בניך וצאנך ובקרך וכל אשר לך
@28 **ואמר פן תורש אתה וביתך** . דרך כבוד כי לאחיו אמר כי למחיה שלחני אלהים לפניכם ולשום לכם שארית שהיו מתים ולא ישאר להם שארית אבל לאביו לא רצה לאמר כן ואמר שאם תתעכב בארץ כנען תורש כי אני לא אוכל לשלוח לך לארץ כנען לחם רב מגנזי המלך כי יחשדו אותי שאני מוכרו שם לעשות לי שם אוצרות כסף ולשוב אל ארצי ואל מולדתי ובבואכם וידעו כי אתם אבי ואחי יתן לי המלך רשות
@29 **כי פי המדבר אליכם** . בלשון הקדש (בלי מליץ זה) דעת המפרשים (רש"י הראב"ע והרד"ק) והוא תרגום אונקלוס ויתכן שאמר להם כך לאמתלא ולפיוס כי איננה ראיה שידבר אדם אחד במצרים בלשון הקדש כי על דעתי הוא שפת כנען כי אברהם לא הביאו מאור כשדים ומחרן כי ארמית היא והגל הזה עד ואיננו לשון לאיש אחד לבד אבל הוא לשון כנען ורבים במצרים יודעים אותו כי קרוב הוא ואף כי המושל שדרך המלכים והמושלים לדעת הלשונות וכמו שתראה בנבוכדנצר שאמר בלשון הקדש (דניאל ב ג) חלום חלמתי ותפעם רוחי לדעת את החלום בעבור שהיו שם חרטומים ואשפים ומכשפים וכשדים מלשונות רבים ומישראל וכולם יבינו אותו והם ענו לו בארמית וידברו הכשדים למלך ארמית כי הם היו הקרובים אליו היושבים ראשונה במלכות ולהם היה הרשות לדבר אל המלך ועוד כי כאשר בא יוסף משם למצרים יבאו רבים ויותר היה להם ראיה בהזכירו שמו וענין המכירה אני יוסף אחיכם אשר מכרתם אותי מצרימה והנכון בעיני כי יאמר והנה עיניכם רואות ועיני אחי בנימן כי אני המושל והאדון לכל מצרים המגיד לכם מפי כי אני אחיכם ומצוה להוריד אבי אלי לכלכלו אם כן תגידו לאבי את כל הכבוד ואת כל אשר ראיתם בעיניכם ותמהרו להורידו אלי כי הדברים אמת ויש בי כח להצילו ולהחיותו ברעב והוא כמו כי פי אני דברתי ובגמרא במסכת מגילה (טז) אמרו כפי כן לבי
@33 **וטעם באו אחי יוסף** . כי היה יוסף מגיד לבית פרעה כי יש לו אחים נכבדים בארץ העברים כי גנב גונב משם ועתה שמעו כי באו אחי יוסף כאשר אמר
@33 "וייטב בעיני פרעה ובעיני עבדיו" - כי היה הדבר להם לחרפה שימשול בהם איש נכרי עבד מבית האסורים יצא למלוך ועתה בבוא אליו אחים נכבדים ונודע כי הוא הגון להתיצב לפני מלכים שמחו כולם בדבר
@36 **ואתה צויתה זאת עשו** . אמר הדבר בצואה לו מדעתו מוסר יוסף כי איננו שולח יד בהון המלך ולא ידע אתו מאומה על כן חשב פרעה אולי לא ירצה לשלוח לאביו דבר על כן אמר לו אני מצוה אותך שתעשה זאת על כל פנים
@40 **ולאביו שלח כזאת** . כחשבון הזה ומהו החשבון עשרה חמורים וגו' לשון רש"י ואיננו נכון שירמוז על החשבון אבל יתכן שיאמר כזאת המנחה ויהי שעורו ולאביו שלח זאת המנחה עשרה חמורים וגו' והכ"ף כאילו יתירה רק דרך הלשון לדבר כן כמו ותדבר אליו כדברים האלה עשה לי עבדך (לעיל לט יט) או יאמר ולאביו שלח צידה כצידה הזאת אשר נתן לאחיו ולא להשוותן רק כאשר נתן להם צידה לדרך בלכתם כן שלח לאביו בר ולחם ומזון לדרך בבואו והוא הנכון והזכיר חמורים ואתונות כי המשא ונושא המשא הכל שלח לו והמנהג לשלוח זכרים ונקבות כאשר עשה אביו (לעיל לב טז)
@41 **אל תרגזו בדרך** . רגז לשון רתת ותנועה ויאמר בבאו מן הפחד על הרוב לב רגז (דברים כח סה) ורגזו וחלו (שם ב כה) ותחתי ארגז (חבקוק ג טז) ומימיך ברגזה ובדאגה תשתה (יחזקאל יב יח) ולכן הנכון בעיני בפסוק הזה שאמר להם יוסף אל תפחדו בדרך והענין כי בעבור נשאם בר ולחם ומזון וטוב מצרים בימי הבצרות יפחדו אולי בדרך בלכתם יבואו עליהם לסטים וכל שכן בשובם עם כל רכושם ולא ימהרו לדבר ולכן אמר להם שילכו בזריזות וימהרו לבא כמו שנאמר (בפסוק ט) מהרו ועלו אל אבי ואל יפחדו כלל בדרך כי שמו עליהם שהוא המושל בכל ארץ מצרים וחיי כל הארצות ההם בידו וממוראו ייראו הכל וילכו ויבאו לשלום
@43 **ויפג לבו** . נחלף לבו והלך מלהאמין לא היה לבו פונה אל הדברים לשון מפיגין טעמן לשון משנה (גמ' ביצה יד) וכמו מאין הפוגות (איכה ג מט) וריחו לא נמר (ירמיהו מח יא) מתורגם וריחיה לא פג לשון רש"י ואיננו נכון כי לשון פוגה שביתה וביטול כמו אל תתני פוגת לך (איכה ב יח) וכן עיני נגרה ולא תדמה מאין הפוגות (שם ג מט) שנגרה תמיד מאין שביתה והפסק וכן מפיגין טעמן שמפזרין אותו ומתבטל וכן על כן תפוג תורה (חבקוק א ד) תבטל ותפסק וגם זה ויפג לבו שנתבטל לבו ופסקה נשימתו כי פסקה תנועת הלב והיה כמת וזה הענין ידוע בבוא השמחה פתאום והוזכר בספרי הרפואות כי לא יסבלו זה הזקנים וחלושי הכח שיתעלפו רבים מהם בבוא להם שמחה בפתע פתאום כי יהיה הלב נרחב ונפתח פתאום והחום התולדי יוצא ומתפזר בחיצוני הגוף ויאפס הלב בהתקררו והנה נפל הזקן כמת ואמר כי לא האמין להם להגיד שעמד זמן גדול מן היום והוא שוכב דומם בעבור שלא האמין להם כי הידוע בעלוף הזה שיצעקו לו וירגילו אותו בשמחה ההיא עד שתקבע בו בנחת רוח וזה טעם וידברו אליו את כל דברי יוסף אשר דבר אליהם וירא את העגלות כי היו צועקים באזניו דברי יוסף ומביאים לפניו העגלות אז שבה רוחו אליו וחזרה נשימתו וחיה וזהו ותחי רוח יעקב אביהם ואונקלוס תרגם ושרת רוח נבואה בעבור שהדבר אמת הוסיף זה ודרש כן במלת רוח שלא אמר "ויחי יעקב אביהם" ועשאו מענין רוח ה' אלהים עלי (ישעיהו סא א) ועתה ה' אלהים שלחני ורוחו (שם מח טז) איש אשר רוח בו (במדבר כז יח)
@44 **וידברו אליו את כל דברי יוסף** . יראה לי על דרך הפשט שלא הוגד ליעקב כל ימיו כי אחיו מכרו את יוסף אבל חשב כי היה תועה בשדה והמוצאים אותו לקחוהו ומכרו אותו אל מצרים כי אחיו לא רצו להגיד לו חטאתם אף כי יראו לנפשם פן יקצוף ויקללם כאשר עשה בראובן ושמעון ולוי (להלן מט ג-ז) ויוסף במוסרו הטוב לא רצה להגיד לו ולכך נאמר ויצוו אל יוסף לאמר אביך צוה לפני מותו לאמר וגו' ואלו ידע יעקב בענין הזה היה ראוי להם שיחלו פני אביהם במותו לצוות את יוסף מפיו כי ישא פניו ולא ימרה את דברו ולא היו בסכנה ולא יצטרכו לבדות מלבם דברים
@46 **ויזבח זבחים לאלהי אביו יצחק** . חייב אדם בכבוד אביו יותר מכבוד זקנו לפיכך תלה ביצחק ולא באברהם לשון רש"י ואיננו מספיק שהראוי לומר לאלהי אבותיו בלי שייחד אדם כמו שאמר האלהים אשר התהלכו אבותי לפניו אברהם ויצחק (להלן מח טו) ובתפלתו אמר אלהי אבי אברהם ואלהי אבי יצחק (לעיל לב י) או יאמר ויזבח זבחים לה' כמו שאומר באברהם (לעיל יב ז) ויבן מזבח לה' ומה צורך לפרש בו יותר אבל הפסוק הזה יש בו סוד יגלו לנו אותו שם בבראשית רבה (צד ה) כי כאשר בא יעקב לרדת מצרים ראה כי הגלות יתחיל בו ובזרעו ופחד ממנו וזבח זבחים רבים לפחד אביו יצחק שלא תהא מדת הדין מתוחה כנגדו ועשה זה בבאר שבע שהוא בית תפלה לאבותיו ומשם נטל רשות בלכתו לחרן ואמר הכתוב זבחים להודיע שלא היו עולות כאבותיו כי אברהם עולות הקריב ורבותינו אמרו (זבחים קטז) לא הקריבו בני נח שלמים עולות הקריבו ובנח כתוב מפורש (לעיל ח כ) ויעל עולות במזבח אבל יעקב מפני פחד ה' הקריב שלמים להשלים אליו כל המדות כמו שדרשו (תורת כהנים ויקרא טז א) שלמים שמטילין שלום בעולם והנה היתה תחלת כונתו במדת הגבורה שהיא הקרובה אליו וזהו הטעם שהזכירו בבראשית רבה (צד ה) שחייב אדם בכבוד אביו יותר מכבוד זקנו והוא הטעם שאמרו שם בלשון אחר בתחילה שואלין בשלום התלמיד ואחר כך שואלין בכבוד הרב וראיתי במדרשו של רבי נחוניא בן הקנה (ספר הבהיר קלה) בלשון הזה וישבע יעקב בפחד אביו יצחק (לעיל לא נג) וכי יש אדם שנשבע כך באמונת פחד אביו אלא עדיין לא נתן ליעקב כח ונשבע בכח שנתן לאביו שנאמר וישבע יעקב בפחד אביו יצחק ומאי ניהו הוא דכתיב ביה (מלכים א יח לח) ותפול אש ה' ותאכל את העולה וכתיב (דברים ד כד) כי ה' אלהיך אש אוכלה הוא וגו' עד כאן במדרש ומדבריהם נלמוד שמפני כן לא אמר ויזבח זבחים לה' לפי שעתה כבר זכה יעקב בחלקו שנאמר (מיכה ז כ) תתן אמת ליעקב חסד לאברהם אשר נשבעת לאבותינו מימי קדם והוצרך לפרש עתה והנה בזכות הקרבנות נראה אליו אלהי יצחק אביו במראות הלילה במדת הדין רפה זהו שאמר אלהים במראות הלילה והוא מה שאמר אנכי האל אלהי אביך כי הוא האל בית אל אשר אמר לו בחרן אנכי האל בית אל אשר משחת שם מצבה (לעיל לא יג) והוא אלהי אביך הוא השם והיא המדה והבטיחו שלא יירא במצרים כי יזכה בדינו ויגאל אחר הענוי וזהו טעם ואנכי אעלך גם עלה וכתב הרב בפרק כז בחלק הראשון במורה הנבוכים כי תרגום אנכי ארד עמך מצרימה ואנכי אעלך גם עלה אנא איחות עמך ואנא אסקינך ונפלא הרב בזה על דעת אונקלוס ואמר כי אונקלוס שם כל מאודו להרחיק הגשמות בכל סיפור אשר בתורה וכל אשר ימצא מאלו השמות המורים על מין ממיני התנועה ישים ענין התנועה לכבוד נברא או לשמירה מהאל ומתרגם וירד ה' (שמות יט כ) ואיתגלי ה' ארדה נא ואראה (לעיל יח כא) איתגלי כען ואיחזי ואם כן למה תרגם כאן אנא איחות ופירש הרב כי בעבור שאמר בתחלת הענין ויאמר אלהים לישראל במראות הלילה לא היה קשה לאונקלוס לספר המאמר כאשר נאמר במראות הלילה כי הוא סיפור אמירה לא סיפור מעשה שהיה כי יש הפרש גדול בין מה שיאמר בחלום או במראה הלילה ובין מה שיאמר במחזה ובמראה ובין מה שיאמר בדבר מוחלט ויהי דבר ה' אלי לאמר או ויאמר ה' אלי לאמר אלו דבריו וכן אמר (הרמב"ם במו"נ א מז) שהרחיק אונקלוס השמיעה בכל מקום וישים פירושה הגעת הדבר ההוא לבורא או קבול תפלה ויתרגם שמיע קדם ה' (לעיל כט לג) וקבלא אקביל קבילתיה (שמות כב כב) ואם כן הדבר כדברי הרב למה יברח אונקלוס מן התנועה וירחיק השמיעה גם כן מיראתו שתורה על גשמות ולא יברח מן האמירה והדבור ולא מן הקריאה בשום מקום בין בחלום בין במראה בין במאמר מוחלט כי בכולם יתרגם ואמר ה' ומליל ה' וקרא ה' למשה והיא גם היא תורה על גשמות והיה לו לתרגם ויתאמר מן קדם ה' או ואמר יקרא דה' או ויתרעי ה' כפי הראוי בענין כמו שפירש הרב בדיבור ובאמירה (מו"נ א סד) ולמה ירחיק בשמיעה ולא ירחיק הראיה שתרגם אותה וחזא ה' ואשר אמר הרב (שם מז) כי יורה על ענין השגת שכל כאשר יורה על השגת העין כל שכן שהוא זה בשמיעה כי היא תאמר על ההשגה בשכל וברצון ברוב מקומות כגון וישמע אברם לקול שרי (לעיל טז ב) שמע קול תחנוני (תהלים כח ב) גם כי תרבו תפלה אינני שומע (ישעיהו א טו) הנה שמוע מזבח טוב (שמואל א טו כב) והיה אם שמוע תשמע בקול ה' אלהיך (דברים כח א) וכן לב שומע (מלכים א ג ט) וכן רובם והנה אונקלוס לא היה לו לירא מן השמיעה שלא תורה רק על קבלת הדבר והרצון בו ולא ברח מן הראיה בשום מקום אבל תרגם אותה כפשוטה בכל מקום שהדבר מושג בראיה בלבד אבל כאשר איננו מושג בראיה בלבד והוא צריך השגחה והתבוננות יתרגם כפי הראוי בו כאשר אמר (לעיל כט לב) כי ראה ה' בעניי ראה ראיתי את עני עמי (שמות ג ז) וירא אלהים את בני ישראל (שם ב כה) שאין הראיה בהם שיראה את גופם אבל שישגיח בענינם וידע אותו וזה דרכו בכל התורה לא כטעם שעלה בדעת הרב ונשתבש בידו והשני מקומות האחרים שתרגם אותם (לעיל ו יב כט לא) וחזא אליו ולא השלים אותו ובלשון העברה כנה אונקלוס ותרגם ויעבר ה' על פניו (שמות לד ו) ואעביר ה' שכינתיה על אפוהי שיהיה הדבר העובר נברא לדעתו ולא יזכיר לשון תנועה בבורא כפי מה שהזכיר הרב ואם כן איך תרגם ה' אלהיך הוא עובר לפניך (דברים לא ג) ה' אלהיך הוא עבר קדמך והנה זה מין תנועה בספור מעשה ולא ירא ממנו אונקלוס וכן בפסוק וירא ישראל את היד הגדולה (שמות יד לא) תרגם בו וחזא ישראל ית גבורתא ידא רבתא נופל בו הגבורה מפני לשון אשר עשה והשאיר בו ידא רבתא ולא היה ירא ומתפחד מן היד ולא יכנה אותה כלל וכן נהג בתרגום כתובים באצבע אלהים (שם לא יח) באצבעה דה' ומה שתירץ בו הרב (במו"נ א סה) כי ישים אונקלוס האצבע כלי נברא אשר פתח הלוחות בחפץ הבורא איננו אמת כי הנה מימינו אש דת למו (דברים לג ב) כתב ימיניה ולא פחד מן הימין הכותבת שתורה על גשמות וכן מן האצבע ועוד תרגם (שמות טו יב) ארימת ימינך ואמר (שם פסוק ו) ימינך ה' תברת שנאה ותרגם ידך החזקה (דברים ג כד) ית ידך תקיפא ואמר (שם ד לד) בידא תקיפא ובאדרעא מרממא וכן ותאחז במשפט ידי (שם לב מא) ותתקיף בדינא ידי וכן תרגם (שם יא יב) תדירא עיני ה' אלהיך בה מרישא דשתא והנה ביעקב כתוב בתחילת הענין ויחלום והנה סולם מוצב ארצה וגו' (לעיל כח יב) ופחד אונקלוס ממנו ותרגם והא יקרא דה' מעתד עלוהי ולא תרגם והא ה' בעבור שהוא בחלום ותרגם והנה אנכי עמך (שם טו) והא מימרי בסעדך ולא אמר והא אנא עמך כמו שתרגם אנא אחות עמך ואף על פי שהוא ספור דבר שנאמר בחלום כמוהו בשוה ותרגם ואנכי אהיה עם פיך (שמות ד יב) ואנא אהי עם פומך ואמר בויאמר כי אהיה עמך וזה לך האות (שם ג יב) ארי יהא מימרי עמך ועוד נזהר אונקלוס בחלומות ותרגם ויבא אלהים אל אבימלך בחלום הלילה (לעיל כ ג) ויבא אלהים אל לבן בחלום (לעיל לא כד) ואתא מימר מן קדם ה' ואם תאמר שחשש שלא תהא הביאה קודמת לחלום ויחשוב בה שהיא ממש הנה בשלמה כתוב (מלכים א ג ה) בגבעון נראה ה' אל שלמה בחלום הלילה ותרגם אותו יונתן אתגלי ה' לשלמה ואם הדבר נאמר בחלום יספרו אותו כאשר נאמר בחלום ההוא ואל יקשה עליהם אף על פי שהוא מאמר יורה על הגשמות כי היותו בחלום יתרץ להם שאינו ממש גם כן הדבר שיאמר כי הוא נראה בחלום ראוי שיספרו אותו באשר הוא כי מה שנאמר בו שהוא בחלום הלילה ילמד שאינו ממש אבל הוא חלום שנדמה לו ממנו כן ואל תחשוב שהיה זה ליונתן בן עוזיאל מפני שלא יאמר בארמית לשון ראיה בחלומות כי וארא בחלומי (לעיל מא כב) מתורגם וחזית ובנבוכדנצר חזה הוית (דניאל ב לא) וכן תרגם אונקלוס לא עלינו תלונותיכם כי על ה' (שמות טז ח) אלהין על מימרא דה' ואין כאן יראה ופחד מן הגשמות וכן וידבר העם באלהים ובמשה (במדבר כא ה) ואתרעם עמא על מימרא דה' וכן ביני וביניכם (לעיל ט יב) בין אלהים ובין כל נפש חיה (שם טז) בין מימרי ומימרא דה' וכיוצא בהן הרבה וכן תרגם יצף ה' (שם לא מט) יסך מימרא דה' אלהים עד (שם לא נ) מימרא דה' סהיד ואין לו בהן יראת הגשמות וגם אין למימרא ענין בכאן שיאמר בו שיצפה ויעיד וכן השבעה לי באלהים (שם כא כג) קיים לי במימרא דה' ואין הנשבעים מזכירין אני נשבע במאמר אלהים וכיוצא באלו רבים לאונקלוס וסודם ידוע למשכילים וכן בלשון עמידה אמר הרב (במו"נ א כז) ששם יונתן בן עוזיאל כוונתו לפרש בו קיום ולכך תרגם ועמדו רגליו (זכריה יד ד) ויתגלי בגבורתיה וכן תרגם כל דבר עסק ותנועה גבורתא והנה אונקלוס לא יתיירא מלשון עמידה ותרגם הנני עומד לפניך שם על הצור (שמות יז ו) הא אנא קאים קדמך תמן על טינרא ומה שאמר הרב (שם) כי אונקלוס ישים ענין התנועה גלוי השכינה והראות כבוד נברא הנה אונקלוס מן הכבוד יברח מלתת בו כלשונות האלה ויתרגם וירא כבוד ה' אל כל העדה (במדבר טז יט) ואתגלי יקרא דה' כמו שיאמר ואתגלי ה' (שמות יט כ) ולא יתרגם ואיתחזי יקרא דה' וכן יתרגם במלאכים (שם ג ב) ואתגלי ואם ידבר אונקלוס במלאכים ובכבוד נברא בעניני הגשמות כמו שאמר הרב (במו"נ א כו) היה ראוי שלא יתיירא מן הראיה שיראה האדם ויתרגם בהם ואתחזי כמו שעשה כי ראיתי אלהים פנים אל פנים (לעיל לב לא) ארי חזיתי מלאכא דה' וחס ושלום שיהיה הדבר הנקרא שכינה או כבוד נברא חוץ מהשם הנכבד יתברך כאשר חשב הרב כאן ובפרקים רבים מספרו והוא תרגם אם אין פניך הולכים (שמות לג טו) אם לית שכינתך מהלכא ביננא ומשה לא יחפוץ בלכת עמו כבוד נברא חוץ מהשם הנכבד יתברך שכבר אמר לו הקדוש ברוך הוא הנה מלאכי ילך לפניך (שם לב לד) ולא היה מתרצה בכך אבל היה מבקש שילך עמו האל בעצמו ובכבודו (שם לג יד) וכן אחר ששמע השם בקולו ואמר לו גם את הדבר הזה אשר דברת אעשה (שם יז) אמר משה ילך נא אדני בקרבנו (שם לד ט) תהך כען שכינתא דה' ביננא וכן תרגם לא תוכל לראות את פני (שם לג כ) לא תוכל למחזי אפי שכינתי ארי לא יחזינני אינשא ואמר יונתן בן עוזיאל (יחזקאל ג יב) בריך יקרא דה' מאתר בית שכינתיה ואם הכבוד הזה ירצה בו הכתוב עצם הבורא ואמתו ויהיה כמו הראני נא את כבודך (שמות לג יח) שפירש בו הרב כן (מו"נ א נג סג) הנה הזכיר בו אתר ובית שכינתיה ואם יאמר שהוא כבוד נברא כדעתו של הרב בפסוק וכבוד ה' מלא את המשכן (שמות מ לה) וזולתו איך יקבעו בו ברוך והמברך והמתפלל לכבוד נברא כעובד אלילים ובדברי רבותינו דברים רבים יורו על שם השכינה שהוא האל יתברך אבל הענינים האלה לאונקלוס ויונתן בן עוזיאל דברים ידועים בקבלה וסודם ליודעים חן ובמעמד הר סיני יתרגם אונקלוס כל מלת אלהים הנזכר בפרשה יקרא או מימרא דה' וכאשר תזכיר הפרשה השם המיוחד לא יאמר כן והכל בהשגחה ובחכמה ממנו ועוד אזכיר זה בעזרת השם יתברך (שמות כ יט) ומה שתרגם אונקלוס וידבר אלהים את כל הדברים האלה (שם כ א) ומליל ה' טעמו בזה משום שנאמר פנים בפנים דבר ה' אל כל קהלכם (דברים ה ד יט) והמשכיל יבין אבל מה שאמר כאן אנא אחות עמך רצה לרמוז בו מה שאמרו (מכילתא שירה ג) גלו למצרים שכינה עמהם שנאמר אנכי ארד עמך מצרימה גלו לעילם שכינה עמהם שנאמר (ירמיהו מט לח) ושמתי כסאי בעילם והנה האמירה והירידה שוים כמו שפירשתי למעלה ולא היה יכול לתרגם אלא כן בשום פנים כאשר רמזתי (ריש פסקא זו) אבל שם ביעקב לא יתכן לתרגם והא אנא עמך בעבור כי שם כתוב והנה ה' נצב עליו (לעיל כח יג) והמשכיל יבין ומפני שמצא אונקלוס שאינו כפשוטו ממש ברח ממנו ועשאו ענין עזר בלבד ואמר מימרי בסעדך ולא אמר מימרי עמך כמו שאמר במשה (שמות ג יב) והאל יראנו מתורתו נפלאות
@47 **ויאמר יעקב יעקב** . אחר שאמר לו השם לא יקרא שמך עוד יעקב כי אם ישראל יהיה שמך היה ראוי שיקראנו בשם הנכבד ההוא וכן הוא נזכר בפרשה הזאת שלשה פעמים אבל קראו יעקב לרמוז כי עתה לא ישור עם אלהים ועם אנשים ויוכל אבל יהיה בבית עבדים עד שיעלנו גם עלה כי מעתה הגלות תתחיל בו וזה טעם ואלה שמות בני ישראל הבאים מצרימה יעקב ובניו (פסוק ח) כי בשם בני ישראל יבאו שמה כי יפרו הבנים וירבו ויגדל שמם וכבודם אבל יעקב הוא עתה ברדתו שם והזכיר הכתוב ער ואונן עם שמות בני ישראל הבאים מצרימה לסוד ידוע מדברינו שכתבנו כבר (לעיל לח ח) והמשכיל יבין זה וטעם כל הפסוק וכן הזכירם בפקודים (במדבר כו יט-כ) בני יהודה ער ואונן וימת ער ואונן בארץ כנען ויהיו בני יהודה למשפחותם ובדברי הימים (א ב ג-ד) מנאם במספר אמר בני יהודה ער ואונן ושלה שלושה נולד לו מבת שוע הכנענית ותמר כלתו ילדה לו את פרץ ואת זרח כל בני יהודה חמשה
@52 **ובנות בניו** . שרח בת אשר ויוכבד בת לוי לשון רש"י ומה ירבה בבנותיו אבל דרך הכתוב כשידבר ביחוסי הרבים יאמר ביחיד לשון רבים ובני דן חושים (להלן פסוק כג) ובני פלוא אליאב (במדבר כו ח) וכן בנותיו דינה ובנות בניו סרח בת אשר אבל יוכבד לא יזכירנה הכתוב כמו שאמר כל נפש ששים ושש אבל ירמוז אליה כדעת רבותינו (ב"ב קכג)
@60 **שלשים ושלש** . ובפרטן אי אתה מוצא אלא שלשים ושתים אלא זו יוכבד שנולדה בכניסתן לעיר שנאמר (במדבר כו נט) אשר ילדה אותה ללוי במצרים לידתה במצרים ואין הורתה במצרים זו היא שיטת רבותינו (סוטה יב) ורבי אברהם השיב ואמר כי זה תימה אם כן למה לא הזכיר הכתוב הפלא שנעשה עמה שהולידה משה והיא בת מאה ושלשים שנה ולמה הזכיר דבר שרה שהיתה בת תשעים ולא די לנו זה הצער עד שעשו הפייטנים פיוטים ביום שמחת תורה יוכבד אמי אחרי התנחמי והנה היא בת מאתים וחמשים שנה וכי אחיה השילוני חיה כך וכך שנים דרך הגדה או דברי יחיד אלו דבריו והנה פן יהיה חכם בעיניו בסתירת דברי רבותינו אני צריך לענות אליו ואומר כי על כל פנים יהיה בדבר יוכבד פלא גדול מן הנסים הנסתרים שהם יסוד התורה כי היא בת לוי עצמו לא מתיחסת אליו כמו שכתוב (במדבר כו נט) אשר ילדה אותה ללוי במצרים ועוד כתוב (שמות ו כ) את יוכבד דודתו והנה אם נאמר כי הוליד אותה בבחרותו כאשר הוליד כל בניו והיתה לידתה אחר רדתו למצרים מעט הנה היא בלדת משה זקנה מאד כמנין שאמרו רבותינו או קרוב לו ואם נאמר שנולדה לו אחר שבתו במצרים ימים רבים והנה נחשוב שהוליד אותה אחר רדתו למצרים חמשים ושבע שנה והוא יהיה בן מאה שנה כי ברדתו היה בן מ"ג שנים והנה יהיו בזה שני פלאים שיהיה הוא זקן כאברהם אשר הזכיר הכתוב (לעיל יז יז) הלבן מאה שנה יולד וכתיב (לעיל יח יב) ואדני זקן ותהיה היא זקנה בלדת משה בת ע"ג ואם נאחר עוד לידתה לסוף ימי לוי הנה יהיה פלא גדול משל אברהם אבל אומר לך דבר שהוא אמת וברור בתורה כי הנסים הנעשים על ידי נביא שיתנבא כן מתחילה או מלאך נגלה במלאכות השם יזכירם הכתוב והנעשים מאליהן לעזור צדיק או להכרית רשע לא יזכירו בתורה או בנביאים וזהו זהב רותח יוצק בפי החכם הזה ממה שהשיב על רבותינו בענין פינחס (במדבר כה יב) וזולתו במקומות הרבה ולמה יזכירם הכתוב כל יסודות התורה בנסים נסתרים הם ועם התורה אין בכל ענינו רק נסים לא טבע ומנהג שהרי יעודי התורה כולם אותות ומופתים כי לא יכרת וימות בטבע הבא על אחת מן העריות או האוכל חלב ולא יהיו השמים כברזל בטבעם מפני זרענו בשנה השביעית וכן כל יעודי התורה בטובות ההן וכל הצלחת הצדיקים בצדקתם וכל תפלות דוד מלכנו וכל תפלותינו נסים ונפלאות אלא שאין בהם שנוי מפורסם בטבעו של עולם כאשר הזכרתי זה כבר (לעיל יז א) ועוד אפרשנו בעזרת השם (שמות ו ב ויקרא כו יא) והנה אתן לך עד נאמן על מה שאמרתי ידענו כי מעת בוא ישראל לארץ עד לדת אדונינו דוד היה כשלש מאות ושבעים שנה והימים יתחלקו לארבעה דורות שלמון ובועז ועובד וישי ויגיע לכל אחד מהם צ"ג שנה והנה כלם זקנים קרוב לאברהם והיו מולידים כל אחד בשנת מותו שלא כדרך כל הארץ כי אין החיים בזמנם מאה שנה ואם הוליד אחד מהם בבחרותו כמנהג יהיו האחרים זקנים מאד יותר מאברהם ויהי בהם הפלא גדול יותר מאד כי ימי האדם בדור אברהם ארוכים ובשנות דוד חזרו למחציתם ואולי חיו יותר כי אפשר שהיו לשלמון ימים רבים בבואם לארץ ולכן נתנו אנשי הקבלה והם חכמי אמת לעובד ימים רבים והוא נס נסתר נעשה לאבי המלוכה בן הצדקת הבאה לחסות תחת כנפי השכינה וכן יזכירו באמו ארך ימים רבים וכבר פרשתי כי הפלא באברהם איננו כאשר יחשוב החכם הנזכר וזולתו מבעלי המקרא כי אברהם הוליד את יצחק טרם מותו שבעים וחמש שנה והנה לא עברו עליו שני חלקים בימיו והאנשים בכל דור אין הזקנה בהם עד עבור עליהם שלשת חלקי ימותם כאשר יחשבו הרופאים הילדות והבחרות והאישות והזקנה ובדורות האלה אשר הימים בהם כשבעים שנה לא יחשבו לו הרופאים זוקן עד אחר ששים ועוד כי אברהם הוליד בנים רבים אחרי ארבעים שנה מלדת יצחק ויהיה הפלא כפלי כפלים ואם נאמר שהחזירו האל לימי בחורותיו יקשה עליו כי לא הזכיר הכתוב הפלא הגדול הזה והוא נס גלוי ומפורסם בהפך מן הטבע ומן הידוע כי האנשים בדור הזה מהם שיולידו בזקנתם עד מלאת שבעים שנה או שמונים שנה ויותר כפי התקומם בהם הלחות לפי טבעם וגם הנשים אין להם זמן וכל עוד היות להן האורח תלדנה רק התימה באברהם ושרה כאשר פירשתי שם מפני שלא הולידו בנעוריהם ועתה הולידו זה מזה ועוד בשרה היה פלא כי חדל ממנה ארח כנשים ואחרי כן לא תלדנה והנה אם יהיו ימי יוכבד כימי אביה ותתקיים בה הלחות עד קרוב לזקנתה כמשפט הנשים איננו פלא אם תוליד בזמן אשר נתנו לה רבותינו מפני שרצה האלהים לגאול את ישראל על ידי האחים האלה ולא הגיע הקץ איחר לידתם ימים רבים עד כי זקנה אמם ולא יפלא מה' דבר
@63 **אלה בני זלפה** . וגו' בני רחל אשת יעקב וגו' דרך הכתוב למנות בני הגבירות יחד בתחילה כמו שאמר בסדר וישלח יעקב (לעיל לה כג-כו) ובסדר ואלה שמות בני ישראל (שמות א ב-ד) או למנותם כתולדותם הבכור כבכורתו והצעיר כצעירתו כאשר עשה בברכתם בסדר ויחי יעקב אבל בכאן מפני שבא למנות מספרם כי בשבעים נפש ירדו מצרימה הקדים המרובה בנפשות ולכך הזכיר רחל בתוך הלחינות והוצרך להזכירה בכבוד ואמר אשת יעקב כאשר הזכרתי למעלה (לא לג מד כז)
@64 ראו רמב"ן על בראשית מו יח
@74 **וירא אליו** . יוסף נראה אל אביו ויבך על צואריו עוד לשון הרביית בכיה אבל יעקב לא נפל על צואר יוסף בנו ולא נשקו ואמרו רבותינו שהיה קורא קריאת שמע לשון רש"י ולא ידעתי טעם ב"וירא אליו" כי בידוע שנתראו כאשר נפל על צוארו ועוד כי איננו דרך כבוד שיפול יוסף על צוארי אביו אבל שישתחוה לו או שינשק ידיו ככתוב (להלן מח יב) ויוצא יוסף אותם מעם ברכיו וישתחו לאפיו והשעה הזו ראויה יותר להשתחות לו וכן כל "עוד" בכתוב תוספת על עיקר הוא איננו כמו הרבה לא על איש ישים עוד (איוב לד כג) שישים עליו כפי חטאיו ולא יותר והנכון בעיני כי כבר היו עיני ישראל כבדים קצת מזוקן וכשבא יוסף במרכבת המשנה ועל פניו המצנפת כדרך מלכי מצרים לא היה ניכר לאביו וגם אחיו לא הכירוהו לפיכך הזכיר הכתוב כי כאשר נתראה אל אביו שהביט בו והכירו נפל אביו על צוארו ובכה עליו עוד כאשר יבכה עליו תמיד עד היום הזה כשלא ראהו ואחר כך אמר אמותה הפעם אחרי ראותי את פניך ודבר ידוע הוא מי דמעתו מצויה אם האב הזקן המוצא את בנו חי לאחר היאוש והאבל או הבן הבכור המולך ואל תחוש בעבור אמרו ויאמר ישראל כי ממנו ידבר ויחזור ויזכיר שמו וכן (לעיל מא מח-נ) ויקבוץ את כל אוכל שבע שנים וגו' וליוסף יולד שני בנים וכן במקומות רבים תמיד בתורה ובמקרא
@77 **והאנשים רעי צאן כי אנשי מקנה היו** . אמר להם שהם רועים אבל לא שירעו בהמות של אחרים כי גם בשל עצמם יש להם עבדים ובני בית ירעו אותם אלא שעשרם במקנה וזה טעם כי אנשי מקנה היו והיה להם עושר ועבודה רבה מאד במקנה רב אשר להם כי לא רצה להזכיר רק לכבוד
@83 **לגור בארץ באנו כי אין מרעה לצאן אשר לעבדיך** . אני תמה בטעם הזה שאמרו לו כי גם במצרים אין מרעה כי כבד הרעב בארץ מצרים כמו בארץ כנען או יותר כי עליה היתה עיקר הגזירה ואולי אמרו כי בארץ כנען מפני כובד הרעב יאכלו האנשים עשב השדה ולא ישאירו מחיה לבהמה אבל בארץ מצרים יש בה שבר יחיו בה האנשים ותשאר בה מרעה מעט ויתכן שהיה בארץ מצרים מרעה מעט באחו מפני היאורים והאגמים
@84 **אביך ואחיך באו אליך** . הכנסת דברים כאומר הנה שמעתי כי אביך ואחיך באו וארץ מצרים לפניך היא והנכון בעיני שיאמר אביך ואחיך אליך באו לשמע כבודך ועליך השליכו יהבם ראה שתעשה עמהם טובה כי עליך הדבר ויש לאל ידך
@86 **ויברך יעקב את פרעה** . היא שאלת שלום כדרך כל הנראין לפני מלכים לפרקים לשון רש"י ואינו נראה כן שאין מדרך מוסר המלוכה שישאל אדם בשלום המלך וכמו שאמרו (שבת פט) כלום יש עבד שנותן שלום לרבו אבל היה ברכה ממש שדרך הזקנים והחסידים הבאים לפני המלכים לברך אותם בעושר ונכסים וכבוד והתנשא מלכותם וכענין שאמר הכתוב (מלכים א א לא) יחי אדוני המלך דוד לעולם ובצאתו מלפניו חזר וברך אותו ליטול רשות מלפניו ואמרו רבותינו (תנחומא נשא כו) שיעלה נילוס לרגלו
@88 **מעט ורעים היו ימי שני חיי** . לא ידעתי טעם הזקן אבינו מה מוסר הוא שיתאונן אל המלך ומה טעם לאמר ולא השיגו את ימי שני חיי אבותי כי אולי עוד ישיגם ויחיה יותר מהם ונראה לי כי יעקב אבינו זרקה בו שיבה והיה נראה זקן מאד ופרעה תמה על זקנותו כי אין רוב אנשי זמנו מאריכים ימים כל כך שכבר קצרו שנותם ולכן שאל לו כמה ימי שני חייך כי לא ראיתי כמותך זקן בכל מלכותי אז ענה יעקב כי ימיו שלשים ומאת שנה ואל יתמה בהם כי מעט הם כנגד שנות אבותיו שחיו יותר אבל מפני היותם רעים בעמל ואנחה זרקה בו שיבה ונראה זקן מאד
@90 **וטעם ויושב יוסף ויתן להם אחזה וגו'** . שהושיב אותם במיטב הארץ ובאחוזה שנתן להם כי לא רצה שיהיו כגרים בארץ וקנה להם בתים ונחלת שדה וכרם נתן להם וזה מרשות פרעה כי הם אמרו לגור בארץ באנו לא לדור וכשיעבור הרעב נשוב לארצנו ופרעה אמר ליוסף הושב את אביך שיושיבם כאנשי הארץ התושבים בארץ גשן
@93 **וילקט יוסף את כל הכסף וגו'** . סיפר הכתוב זה וגמר הענין בכל הפרשה להודיע מעלות יוסף בחכמה בתבונה ובדעת וכי היה איש אמונים שהביא כל הכסף בית פרעה ולא עשה לעצמו אוצרות כסף ומטמוני מסתרים בארץ מצרים או לשלחו לארץ כנען אבל נתן למלך הבוטח בו כל הכסף וקנה לו את האדמה גם הגופות ומצא בזה חן גם כן בעיני העם כי השם הוא המצליח את יראיו
@94 **ויתם הכסף מארץ מצרים ומארץ כנען ויבאו כל מצרים אל יוסף וגו'** . והזכיר כי תם הכסף מארץ כנען בעבור כי מצרים בבואם אל יוסף יזכירו לו זה כי אמרו אחרי שתם הכסף גם מארץ כנען ולא יבאו עוד אליך לשבור למה נמות נגדך כי אפס כסף ותמיתנו חנם ותשאר התבואה בידך ואין קונה
@97 **ויבאו אליו בשנה השנית** . לשני הרעב ואף על פי שאמר יוסף ועוד חמש שנים אשר אין חריש וקציר (לעיל מה ו) מכיון שבא יעקב למצרים באתה ברכה לרגלו והתחילו לזרוע וכלה הרעב וכן שנינו בתוספתא דסוטה (י ג) לשון רש"י וכך הוזכר בבראשית רבה (פט יא) אמר רבי יוסי ברבי חנינא שתי שנים עשה רעב כיון שירד יעקב אבינו למצרים כלה הרעב ואימתי חזרו בימי יחזקאל וכו' ואם כן לא נתקיימו דברי יוסף כפתרונו ויבא הענין לחשוד אותו בחכמתו ואולי נאמר שהיה הרעב בארץ כנען כדבר יוסף אבל במצרים ירד יעקב אבינו אל היאור לעיני פרעה ולעיני כל מצרים וראו כל עמו שעלה נילוס לקראתו וידעו כי ברכת ה' היא לרגלי הנביא ואם כן יהיה ויכלכל יוסף את אביו ואת אחיו לחם לפי הטף בשאר שני השבע וכל ימי חיות אביו כי גם אחרי מות אביו אמר אנכי אכלכל אתכם ואת טפכם (להלן נ כא) ועם כל זה אני תמה שאם כן לא היה החלום אמת כי הראו לו את הגזרה ולא הענין הנהיה והנעשה בהם וראיתי שם בתוספתא דסוטה אמר רבי יוסי כיון שמת יעקב אבינו חזר הרעב לישנו וכו' ועוד שנינו בספרי (עקב לח) ויברך יעקב את פרעה במה ברכו שנמנע שני הרעב אף על פי כן שלמו אחר מיתתו שנאמר ועתה אל תיראו אנכי אכלכל אתכם מה כלכול האמור להלן (פרק מה יא) בשני רעבון הכתוב מדבר אף כלכול האמור כאן בשני רעבון הכתוב מדבר רבי שמעון אומר אין זה קידוש השם שדברי צדיקים קיימין בחייהם וניטלין לאחר מיתתן אמר רבי אלעזר ברבי שמעון רואה אני את דברי רבי יוסי מדברי אבא שזה קידוש השם שכל זמן שהצדיקים בעולם ברכה בעולם נסתלקו מן העולם נסתלקה ברכה מן העולם עד כאן והנה השלים הרעב חמש השנים הנותרות ודעת רבי אברהם שהיו אלו שתי השנים לאחר בוא יעקב למצרים וכך כתב מצינו בדרש כי נסתלק הרעב בזכות יעקב גם יתכן שהיה רעב שלש שנים ולא היה כמו ד' שעברו ואין דבריו נכונים כלל כי מספר החלום ושברו ישוה כל השבע שנים ואילו היה כן יזכיר הכתוב ענינם של השנים האלה אבל על דרך הפשט לקט יוסף את כל הכסף הנמצא בארץ מצרים ובארץ כנען בחמש שנים והביא אותו אל פרעה כי איך יתכן שיתום הכסף והמקנה בשנה אחת אבל הכסף הספיק להם כל חמש שנים כי כן הדבר במנהגו של עולם ובעבור שלא נתחדש ונשתנה דבר אחד בכל אלה השנים לא ספר בהם הכתוב רק וילקט יוסף את כל הכסף וגו' ואחרי שתם הכסף ספר שבאו אל יוסף והיה זה בשנה הששית ונתן להם במקניהם לחם רק נהלם בו שיאכלו לפי חיותם ולא לשבעה ותתם השנה ההיא אשר נדר להם לנהלם בלחם בכל מקניהם והיא השנה הששית ויבאו אליו בשנה השנית לה ואמרו לו שיקנה אותם ואת אדמתם בלחם שיאכילם בשנה הזאת השביעית ואחר שתהיה הארץ לפרעה יתן להם זרע שלא תשם האדמה כי ידעו כי כלו שבע שני הרעב ויהיה להם זרע וקציר וזה טעם ויכלכל יוסף לחם לפי הטף שנתן להם בשנות הרעב כדי צרכם לחם כי לפי הטף ירמוז כן
@98 **קנה אתנו ואת אדמתנו** . הנה אמרו לו שגם גופם יקנה לעבדים לפרעה וכן אמר הן קניתי אתכם היום ואת אדמתכם אבל אמר ויקן יוסף את כל אדמת מצרים לפרעה כי מכרו מצרים איש שדהו ולא אמר שיקנה גופם רק האדמה והטעם כי הם אמרו לו שיקנה אותם לעבדים עושי מלאכת המלך כרצונו והוא לא רצה רק לקנות את האדמה והתנה עמהם שיעבדו אותה לעולם ויהיו בה אריסי בתי אבות לפרעה ואחרי כן אמר להם הן קניתי אתכם היום ואת אדמתכם לפרעה לא לעבדים כאשר אמרתם לי רק עם האדמה תהיו לו והנה ראוי שיטול המלך שהוא אדון הקרקע ארבע הידות ואתם החמישית אבל אני אתחסד עמכם שתטלו אתם חלק בעל הקרקע ופרעה יטול החלק הראוי לאריס אבל תהיו קנוים לו שלא תוכלו לעזוב את השדות וזה טעם מה שנדרו לו והאדמה לא תשם שלא תשם לעולם ולכך אמרו לו נמצא חן בעיני אדוני שהקלת עלינו ליטול ארבע הידות שנוכל לחיות בהם והיינו עבדים לפרעה כאשר נדרנו שנעבוד את האדמה לרצונו חסלת פרשת ויגש
